    logger.debug(
        "GEMS ADDMM, [shape info]: [-, %s, %s, %s](batch, M, N, K), "
        "[A column-major]: %s, [B column-major]: %s, [bias column-major]: %s",
        mat1.shape[0],
        mat2.shape[1],
        mat1.shape[1],
        mat1.stride(0) == 1,
        mat2.stride(0) == 1,
        bias.ndim > 0 and bias.stride(0) == 1,
    )
    if torch.is_grad_enabled() and (
        bias.requires_grad or mat1.requires_grad or mat2.requires_grad
    ):
        return AddmmFunction.apply(bias, mat1, mat2, beta, alpha)
    return _addmm_impl(bias, mat1, mat2, None, beta, alpha)


